    Bug 1908033 - Prevent the creation of incoming servers with invalid hostnames. r=babolivier
    Except "Local Folders" and "smart mailboxes", of course.

    Differential Revision: https://phabricator.services.mozilla.com/D216640

diff --git a/mailnews/base/src/nsMsgAccountManager.cpp b/mailnews/base/src/nsMsgAccountManager.cpp
index a992b53d7dd..432720c7f53 100644
--- a/mailnews/base/src/nsMsgAccountManager.cpp
+++ b/mailnews/base/src/nsMsgAccountManager.cpp
@@ -545,6 +545,22 @@ nsresult nsMsgAccountManager::createKeyedServer(
   nsresult rv;
   *aServer = nullptr;

+  if (hostname.Equals("Local Folders") || hostname.Equals("smart mailboxes")) {
+    // Allow these special hostnames, but only for "none" servers.
+    if (type != "none") {
+      return NS_ERROR_MALFORMED_URI;
+    }
+  } else if (hostname.Equals("Local%20Folders") ||
+             hostname.Equals("smart%20mailboxes")) {
+    // Don't allow these %-encoded special hostnames.
+    return NS_ERROR_MALFORMED_URI;
+  } else {
+    // Check the hostname is valid.
+    nsAutoCString unused;
+    rv = NS_DomainToASCII(hostname, unused);
+    NS_ENSURE_SUCCESS(rv, rv);
+  }
+
   // construct the contractid
   nsAutoCString serverContractID("@mozilla.org/messenger/server;1?type=");
   serverContractID += type;
diff --git a/mailnews/base/test/unit/test_accountMgr2.js b/mailnews/base/test/unit/test_accountMgr2.js
index 4ece0d1ee29..9ad3d21a501 100644
--- a/mailnews/base/test/unit/test_accountMgr2.js
+++ b/mailnews/base/test/unit/test_accountMgr2.js
@@ -257,4 +257,39 @@ add_task(async function () {
     twoServerNorm?.hostName,
     "should find server by uri for normalized hostname '2'"
   );
+
+  MailServices.accounts.createIncomingServer(
+    "nobody",
+    "smart mailboxes",
+    "none"
+  );
+
+  function checkBadHostname(hostname, error = /NS_ERROR_MALFORMED_URI/) {
+    Assert.throws(
+      () =>
+        MailServices.accounts.createIncomingServer("nobody", hostname, "none"),
+      error,
+      `bad hostname "${hostname}" should fail for "none" type servers`
+    );
+    Assert.throws(
+      () =>
+        MailServices.accounts.createIncomingServer("nobody", hostname, "imap"),
+      /NS_ERROR_MALFORMED_URI/,
+      `bad hostname "${hostname}" should fail for "imap" type servers`
+    );
+  }
+
+  checkBadHostname(" bad.test ");
+  checkBadHostname("b%61d.test");
+  checkBadHostname("b/d.test");
+  checkBadHostname("b:d.test");
+  checkBadHostname("b@d.test");
+  checkBadHostname("b d.test");
+  // Valid for "none" type, but already exists.
+  checkBadHostname("Local Folders", /NS_ERROR_FAILURE/);
+  checkBadHostname("Local Folders 2");
+  checkBadHostname("Local%20Folders");
+  // Valid for "none" type, but already exists.
+  checkBadHostname("smart mailboxes", /NS_ERROR_FAILURE/);
+  checkBadHostname("smart%20mailboxes");
 });
